import{_ as o,o as t,c as r,a4 as a}from"./chunks/framework.BOlBRgXm.js";const p=JSON.parse('{"title":"Production checklist","description":"","frontmatter":{},"headers":[],"relativePath":"guide/production.md","filePath":"guide/production.md","lastUpdated":1791398882000}'),i={name:"guide/production.md"};function n(s,e,c,d,l,h){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="production-checklist" tabindex="-1">Production checklist <a class="header-anchor" href="#production-checklist" aria-label="Permalink to &quot;Production checklist&quot;">​</a></h1><h2 id="styles-and-fonts" tabindex="-1">Styles and fonts <a class="header-anchor" href="#styles-and-fonts" aria-label="Permalink to &quot;Styles and fonts&quot;">​</a></h2><ul><li><strong>KaTeX</strong>: load <code>katex/dist/katex.min.css</code>. <code>createMorph</code> waits for <code>document.fonts.ready</code> before measuring.</li><li><strong>MathJax</strong>: the renderer injects its stylesheet into <code>document.head</code> on first use. For shadow roots, adopt <code>renderer.stylesheet()</code>.</li></ul><h2 id="server-side-rendering" tabindex="-1">Server-side rendering <a class="header-anchor" href="#server-side-rendering" aria-label="Permalink to &quot;Server-side rendering&quot;">​</a></h2><p>Morphing needs real layout, so it runs in the browser only. Render static formulas on the server, then hand them to texmorph on the client with <code>{ adopt: element }</code> (see <a href="/Texmorph/guide/chaining-steps#formula-inputs">Chaining steps</a>).</p><h2 id="resizing" tabindex="-1">Resizing <a class="header-anchor" href="#resizing" aria-label="Permalink to &quot;Resizing&quot;">​</a></h2><p>Call <code>morph.refresh()</code> when the container&#39;s width or the fonts change. The <a href="/Texmorph/integrations/web-component">Web Component</a> does this automatically.</p><h2 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h2><ul><li>Exactly one formula is exposed to assistive technology at any time: the source until the morph completes, then the target. Ghosts are <code>aria-hidden</code>.</li><li>texmorph does not check <code>prefers-reduced-motion</code> itself, because it does not own playback. Respect it in your player, for example by rendering <code>t = 1</code> directly. The Web Component does this for <code>play()</code>.</li></ul><h2 id="content-security-policy" tabindex="-1">Content Security Policy <a class="header-anchor" href="#content-security-policy" aria-label="Permalink to &quot;Content Security Policy&quot;">​</a></h2><p>texmorph writes styles through the CSSOM and never uses <code>innerHTML</code> or <code>eval</code>, so it works under a strict <code>style-src</code> and <code>script-src</code>. When passing styles to the Web Component under CSP, prefer a constructed <code>CSSStyleSheet</code> over a string.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><p>KaTeX&#39;s <code>trust: true</code> is rejected; pass a function that allows specific commands instead. The MathJax renderer refuses the <code>html</code>, <code>require</code> and <code>autoload</code> TeX packages. See <a href="https://github.com/JeffeyChou/Texmorph/blob/main/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a>.</p><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><ul><li>Prepare costs about one render plus measurement per formula. Prepare the next step while the current one is still on screen if latency matters.</li><li><code>render(t)</code> only writes <code>transform</code>, <code>opacity</code> and <code>color</code>; it does not trigger layout.</li><li>Each morph adds one absolutely positioned element per symbol while it is alive. Dispose of morphs you no longer need.</li></ul>',15)])])}const m=o(i,[["render",n]]);export{p as __pageData,m as default};
